24: // AccountStop stops the running app or, when a start is in flight, cancels it
25: // and returns at once without taking s.lock: the start closes whatever it
26: // published on its way out (see the protocol in app_start.go). Cancelling a
27: // pending start is a successful stop even though it leaves no app to close —
28: // the client needs to tell that apart from "nothing was running" to know its
29: // select is coming back.
30: //
31: // RemoveData never takes that shortcut. Cancelling costs no lock wait, but a
32: // client that asked for the account to be erased must not be told the erase
33: // succeeded while the data is still on disk — that is a lie it has no way to
34: // detect. So a removal request cancels the start and then waits for the lock
35: // like any other, and if the start unwound first, leaving no wallet to
36: // resolve the account directory from, it reports the failure rather than
37: // reporting success.
38: func (s *Service) AccountStop(req *pb.RpcAccountStopRequest) error {
39: 	cancelled := s.cancelStart()
40: 	if cancelled && !req.RemoveData {
41: 		return nil
42: 	}
43: 	s.lock.Lock()
44: 	defer s.lock.Unlock()
45: 
46: 	if s.app == nil {
47: 		if cancelled {
48: 			// The stop happened; the removal did not.
49: 			return ErrFailedToRemoveAccountData
50: 		}
51: 		return ErrApplicationIsNotRunning
52: 	}
53: 
54: 	// try to revoke push notification token for mobile clients
55: 	if runtime.GOOS == "android" || runtime.GOOS == "ios" {
56: 		if pushService := s.app.Component(pushnotification.CName).(pushnotification.Service); pushService != nil {
57: 			go func() {
58: 				_ = pushService.RevokeToken(context.Background())
59: 			}()
60: 		}
61: 	}
62: 
63: 	if req.RemoveData {
64: 		err := s.accountRemoveLocalData()
65: 		if err != nil {
66: 			return errors.Join(ErrFailedToRemoveAccountData, anyerror.CleanupError(err))
67: 		}
68: 	} else {
69: 		err := s.stop()
70: 		if err != nil {
71: 			return ErrFailedToStopApplication
72: 		}
73: 	}
74: 	return nil
75: }
