79: 	defer s.lock.Unlock()
80: 	if s.app == nil {
81: 		return ErrApplicationIsNotRunning
82: 	}
83: 	// published only now, under the lock: a restart that superseded the
84: 	// select it was queued behind would find no app left to restart
85: 	ctx, end := s.beginStart(ctx)
86: 	defer end()
87: 
88: 	rootPath := s.app.MustComponent(walletComp.CName).(walletComp.Wallet).RootPath()
