91: 	conf := s.app.MustComponent(config.CName).(*config.Config)
92: 
93: 	if req.NetworkMode == pb.RpcAccount_CustomConfig {
94: 		// check if file exists at path
95: 		b, err := os.ReadFile(req.NetworkCustomConfigFilePath)
96: 		if os.IsNotExist(err) {
97: 			return config.ErrNetworkFileNotFound
98: 		}
99: 		if err != nil {
100: 			return errors.Join(config.ErrNetworkFileFailedToRead, err)
101: 		}
102: 		var cfg nodeconf.Configuration
103: 		err = yaml.Unmarshal(b, &cfg)
104: 		if err != nil {
105: 			// wrap errors into each other
106: 			return errors.Join(config.ErrNetworkFileFailedToRead, err)
107: 		}
108: 		if conf.NetworkId() != "" && conf.NetworkId() != cfg.NetworkId {
109: 			return config.ErrNetworkIdMismatch
110: 		}
111: 	}
