115: 		return errors.Join(ErrFailedToStopApplication, s.releaseAccountLease())
116: 	}
117: 
118: 	_, err = s.start(ctx, accountId, rootPath, conf.DontStartLocalNetworkSyncAutomatically, conf.JsonApiListenAddr,
119: 		conf.PeferYamuxTransport, req.NetworkMode, req.NetworkCustomConfigFilePath, lang, "", conf.EnableMembershipV2, conf.PreferredSpaceId)
120: 	return err
121: }
